<template>
  <section class="proposal-page">
    <header class="proposal-hero"><div><p class="eyebrow">LUNU WORKFLOW / MEDIA REQUESTS</p><h1>Đề xuất <em>media.</em></h1><p>{{ isAdmin ? 'Kiểm duyệt những đề xuất từ cộng đồng trước khi đưa vào kho LuNu.' : 'Bạn muốn nghe hoặc xem một nội dung mới? Gửi đề xuất, admin sẽ kiểm tra và đưa vào kho cho bạn.' }}</p></div><div class="proposal-badge">{{ isAdmin ? pendingCount + ' CHỜ DUYỆT' : 'REQUEST A MOMENT' }}</div></header>

    <div v-if="!isAdmin" class="proposal-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">SUGGEST SOMETHING</span><h2>Tìm nội dung muốn thêm</h2></div><span class="status-dot">● REVIEWED</span></div><div class="search-wrapper"><label class="search-field"><span>⌕</span><input v-model.trim="query" type="search" placeholder="Tìm bài hát, video hoặc nghệ sĩ..." @keyup.enter="search" /></label><button type="button" class="primary-btn" :disabled="searching || !query" @click="search">{{ searching ? 'Đang tìm...' : 'Tìm kiếm' }} →</button></div><p v-if="message" class="status-message" :class="messageType">{{ message }}</p><div v-if="results.length" class="results-list"><article v-for="item in results" :key="item.id" class="result-item"><img :src="item.thumbnail" :alt="item.title" /><div><strong>{{ item.title }}</strong><small>{{ item.uploader || 'YouTube' }}</small></div><button type="button" class="select-btn" @click="choose(item)">Đề xuất</button></article></div><form v-if="selected" class="suggest-form" @submit.prevent="submit"><div class="selected-item"><img :src="selected.thumbnail" :alt="selected.title" /><div><strong>{{ selected.title }}</strong><small>{{ selected.uploader || 'YouTube' }}</small></div></div><label><span>LOẠI MEDIA</span><select v-model="form.kind"><option value="song">Bài hát MP3</option><option value="video">Video MP4</option></select></label><label><span>TÊN HIỂN THỊ</span><input v-model.trim="form.title" required maxlength="240" /></label><label v-if="form.kind === 'song'"><span>CA SĨ</span><input v-model.trim="form.artist" required maxlength="160" placeholder="Nhập tên ca sĩ" /></label><label v-else><span>KÊNH / NGƯỜI ĐĂNG</span><input v-model.trim="form.uploader" maxlength="160" /></label><label class="wide"><span>GHI CHÚ CHO ADMIN</span><textarea v-model.trim="form.description" rows="3" maxlength="1000" placeholder="Vì sao bạn muốn thêm nội dung này?"></textarea></label><div class="form-actions"><button type="button" class="secondary-btn" @click="selected = null">Hủy</button><button type="submit" class="primary-btn" :disabled="submitting">{{ submitting ? 'Đang gửi...' : 'Gửi admin duyệt' }} ↗</button></div></form></div>

    <div class="proposal-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">{{ isAdmin ? 'MODERATION QUEUE' : 'MY REQUESTS' }}</span><h2>{{ isAdmin ? 'Hàng đợi duyệt media' : 'Đề xuất của tôi' }}</h2></div><div class="panel-actions"><select v-if="isAdmin" v-model="filter" @change="load"><option value="">Tất cả</option><option value="pending">Chờ duyệt</option><option value="processing">Đang tải</option><option value="approved">Đã thêm</option><option value="rejected">Từ chối</option><option value="failed">Lỗi</option></select><button type="button" class="refresh-btn" @click="load">↻ Làm mới</button></div></div><div v-if="loading" class="inline-state">Đang đồng bộ đề xuất...</div><div v-else-if="!proposals.length" class="inline-state">{{ isAdmin ? 'Chưa có đề xuất nào.' : 'Bạn chưa gửi đề xuất nào.' }}</div><div v-else class="proposal-list"><article v-for="proposal in proposals" :key="proposal.id" class="proposal-row"><div class="proposal-type" :class="proposal.kind">{{ proposal.kind === 'song' ? '♪' : '▶' }}</div><div class="proposal-copy"><div><strong>{{ proposal.title }}</strong><span class="status-pill" :class="proposal.status">{{ statusLabel(proposal.status) }}</span></div><small>{{ proposal.kind === 'song' ? (proposal.artist || 'Chưa có ca sĩ') : (proposal.uploader || 'YouTube') }} <template v-if="isAdmin"> · {{ proposal.requested_by_username || 'user' }}</template></small><p v-if="proposal.rejection_reason">{{ proposal.rejection_reason }}</p></div><div class="proposal-size">{{ formatBytes(proposal.file_size_bytes) }}</div><div v-if="isAdmin && proposal.status === 'pending'" class="proposal-actions"><button type="button" class="approve-btn" @click="approve(proposal)">Duyệt</button><button type="button" class="reject-btn" @click="reject(proposal)">Từ chối</button></div><time>{{ formatTime(proposal.created_at) }}</time></article></div></div>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { approveMediaProposal, createMediaProposal, getMediaProposals, getMyMediaProposals, rejectMediaProposal, searchYoutube } from '../services/api';
import { authState } from '../store/appState';

const isAdmin = computed(() => authState.user?.role === 'admin');
const query = ref(''); const searching = ref(false); const results = ref([]); const selected = ref(null); const submitting = ref(false); const proposals = ref([]); const loading = ref(false); const filter = ref(''); const message = ref(''); const messageType = ref('');
const form = reactive({ kind: 'song', title: '', artist: '', uploader: 'YouTube', description: '' });
const pendingCount = computed(() => proposals.value.filter((item) => item.status === 'pending').length);
const search = async () => { if (!query.value) return; searching.value = true; message.value = ''; results.value = []; try { const response = await searchYoutube(query.value); if (!response?.success) throw new Error(response?.message || 'Không tìm thấy nội dung.'); results.value = response.results || []; message.value = results.value.length ? `Tìm thấy ${results.value.length} kết quả. Chọn nội dung bạn muốn đề xuất.` : 'Không có kết quả phù hợp.'; } catch (error) { message.value = error.message; messageType.value = 'error'; } finally { searching.value = false; } };
const choose = (item) => { selected.value = item; form.title = item.title || ''; form.artist = ''; form.uploader = item.uploader || 'YouTube'; form.description = ''; message.value = ''; };
const submit = async () => { if (!selected.value) return; submitting.value = true; try { const response = await createMediaProposal({ kind: form.kind, sourceId: selected.value.id, title: form.title, artist: form.artist, uploader: form.uploader, cover: selected.value.thumbnail, description: form.description }); message.value = response.message || 'Đã gửi đề xuất cho admin.'; messageType.value = 'success'; selected.value = null; results.value = []; await load(); } catch (error) { message.value = error.message; messageType.value = 'error'; } finally { submitting.value = false; } };
const load = async () => { loading.value = true; try { proposals.value = isAdmin.value ? await getMediaProposals(filter.value) : await getMyMediaProposals(); } catch (error) { message.value = error.message; messageType.value = 'error'; } finally { loading.value = false; } };
const approve = async (proposal) => { if (!window.confirm(`Duyệt “${proposal.title}” và bắt đầu tải media?`)) return; try { await approveMediaProposal(proposal.id); proposal.status = 'processing'; message.value = 'Đã duyệt. Hệ thống bắt đầu tải media.'; messageType.value = 'success'; } catch (error) { message.value = error.message; messageType.value = 'error'; } };
const reject = async (proposal) => { const reason = window.prompt('Lý do từ chối (không bắt buộc):', 'Nội dung chưa phù hợp với kho LuNu.'); if (reason === null) return; try { await rejectMediaProposal(proposal.id, reason); proposal.status = 'rejected'; proposal.rejection_reason = reason; message.value = 'Đã từ chối và gửi thông báo cho user.'; messageType.value = 'success'; } catch (error) { message.value = error.message; messageType.value = 'error'; } };
const statusLabel = (value) => ({ pending: 'Chờ duyệt', processing: 'Đang xử lý', approved: 'Đã thêm', rejected: 'Từ chối', failed: 'Lỗi' }[value] || value);
const formatBytes = (bytes) => { if (!bytes) return 'Chưa có dung lượng'; const units = ['B', 'KB', 'MB', 'GB']; let size = Number(bytes); let index = 0; while (size >= 1024 && index < units.length - 1) { size /= 1024; index += 1; } return `${size.toFixed(index ? 1 : 0)} ${units[index]}`; };
const formatTime = (value) => { if (!value) return ''; try { return new Date(value).toLocaleDateString('vi-VN'); } catch { return ''; } };
onMounted(load);
</script>

<style scoped>
.proposal-page { max-width: 1180px; margin: 0 auto; padding: 18px 0 70px; }.proposal-hero { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; padding:36px clamp(20px,4vw,54px); border:1px solid rgba(255,255,255,.08); border-radius:25px; background:radial-gradient(circle at 82% 26%,rgba(245,185,122,.18),transparent 28%),linear-gradient(118deg,rgba(38,42,55,.96),rgba(16,19,27,.82)); }.eyebrow,.panel-kicker { color:var(--gold); font:9px var(--font-mono); letter-spacing:1.8px; }.proposal-hero h1 { margin-top:12px; color:var(--text-main); font:500 clamp(40px,5vw,64px)/.95 var(--font-display); letter-spacing:-2px; }.proposal-hero h1 em { color:var(--gold); font-style:italic; }.proposal-hero p:last-child { max-width:600px; margin-top:15px; color:var(--text-sub); font-size:12px; line-height:1.6; }.proposal-badge { padding:10px 12px; border:1px solid rgba(245,185,122,.3); border-radius:10px; color:var(--gold); font:9px var(--font-mono); white-space:nowrap; }.proposal-panel { margin-top:18px; padding:clamp(18px,3vw,28px); border-radius:18px; }.panel-heading { display:flex; align-items:center; justify-content:space-between; gap:15px; }.panel-heading h2 { margin-top:7px; color:var(--text-main); font:500 23px var(--font-display); }.status-dot { color:var(--mint); font:8px var(--font-mono); }.search-wrapper { display:flex; gap:9px; margin-top:18px; }.search-field { display:flex; align-items:center; flex:1; gap:10px; padding:12px 13px; border:1px solid var(--hairline); border-radius:10px; background:rgba(3,5,9,.34); }.search-field:focus-within { border-color:rgba(245,185,122,.6); }.search-field span { color:var(--gold); font-size:18px; }.search-field input { width:100%; border:0; outline:0; background:transparent; color:var(--text-main); font-size:11px; }.primary-btn,.secondary-btn,.refresh-btn,.select-btn,.approve-btn,.reject-btn { border-radius:9px; padding:10px 13px; cursor:pointer; font-size:10px; font-weight:800; }.primary-btn { border:0; background:linear-gradient(135deg,var(--gold-bright),var(--gold)); color:#171218; }.primary-btn:disabled { opacity:.55; cursor:progress; }.secondary-btn,.refresh-btn { border:1px solid var(--hairline); background:transparent; color:var(--text-sub); }.panel-actions { display:flex; align-items:center; gap:8px; }.panel-actions select { border:1px solid var(--hairline); border-radius:8px; padding:9px; background:#151924; color:var(--text-sub); font-size:9px; }.status-message { margin-top:13px; color:var(--text-sub); font-size:10px; }.status-message.success { color:var(--mint); }.status-message.error { color:var(--crimson); }.results-list { display:flex; flex-direction:column; gap:6px; max-height:350px; margin-top:16px; overflow:auto; }.result-item { display:flex; align-items:center; gap:11px; padding:9px; border:1px solid var(--hairline-soft); border-radius:10px; background:rgba(3,5,9,.2); }.result-item img,.selected-item img { width:92px; height:52px; border-radius:7px; object-fit:cover; }.result-item > div,.selected-item > div { display:flex; flex:1; flex-direction:column; min-width:0; }.result-item strong,.selected-item strong { overflow:hidden; color:var(--text-main); text-overflow:ellipsis; white-space:nowrap; font-size:11px; }.result-item small,.selected-item small { margin-top:5px; color:var(--text-sub); font-size:9px; }.select-btn { border:1px solid rgba(245,185,122,.3); background:rgba(245,185,122,.08); color:var(--gold); }.suggest-form { display:grid; grid-template-columns:1fr 1fr; gap:10px; padding-top:17px; margin-top:16px; border-top:1px solid var(--hairline-soft); }.selected-item,.suggest-form label { display:flex; align-items:center; gap:10px; }.suggest-form label { display:grid; align-content:start; gap:6px; }.suggest-form label span { color:var(--text-faint); font:8px var(--font-mono); letter-spacing:1px; }.suggest-form input,.suggest-form select,.suggest-form textarea { width:100%; box-sizing:border-box; padding:10px 11px; border:1px solid var(--hairline); border-radius:8px; outline:0; background:rgba(3,5,9,.3); color:var(--text-main); font-size:10px; }.suggest-form .wide,.form-actions { grid-column:1/-1; }.form-actions { display:flex; justify-content:flex-end; gap:8px; }.proposal-list { margin-top:17px; border-top:1px solid var(--hairline-soft); }.proposal-row { display:grid; grid-template-columns:34px minmax(0,1fr) 120px auto 80px; align-items:center; gap:12px; min-height:68px; border-bottom:1px solid var(--hairline-soft); }.proposal-type { display:grid; place-items:center; width:29px; height:29px; border-radius:9px; background:rgba(245,185,122,.1); color:var(--gold); font-size:14px; }.proposal-type.video { color:#b8adff; background:rgba(155,140,255,.1); }.proposal-copy { min-width:0; }.proposal-copy > div { display:flex; align-items:center; gap:8px; min-width:0; }.proposal-copy strong { overflow:hidden; color:var(--text-main); text-overflow:ellipsis; white-space:nowrap; font-size:11px; }.proposal-copy small { display:block; margin-top:5px; color:var(--text-sub); font-size:9px; }.proposal-copy p { margin-top:5px; color:var(--crimson); font-size:9px; }.status-pill { flex:none; padding:4px 6px; border-radius:5px; font:8px var(--font-mono); }.status-pill.pending { background:rgba(245,185,122,.12); color:var(--gold); }.status-pill.processing { background:rgba(155,140,255,.12); color:#b8adff; }.status-pill.approved { background:rgba(115,226,181,.12); color:var(--mint); }.status-pill.rejected,.status-pill.failed { background:rgba(255,109,125,.12); color:var(--crimson); }.proposal-size { color:var(--text-faint); font:8px var(--font-mono); white-space:nowrap; }.proposal-actions { display:flex; gap:5px; }.approve-btn { border:1px solid rgba(115,226,181,.3); background:rgba(115,226,181,.08); color:var(--mint); }.reject-btn { border:1px solid rgba(255,109,125,.25); background:transparent; color:var(--crimson); }.proposal-row time { color:var(--text-faint); font:8px var(--font-mono); white-space:nowrap; }.inline-state { padding:45px 20px; color:var(--text-sub); text-align:center; font-size:11px; }
@media(max-width:700px){.proposal-hero{align-items:flex-start;flex-direction:column}.proposal-badge{align-self:flex-start}.search-wrapper{display:grid;grid-template-columns:1fr}.suggest-form{grid-template-columns:1fr}.suggest-form .wide,.form-actions{grid-column:1}.form-actions>*{flex:1}.panel-heading{align-items:flex-start;flex-direction:column}.panel-actions{width:100%;justify-content:space-between}.proposal-row{grid-template-columns:30px minmax(0,1fr);gap:9px;padding:12px 0}.proposal-size,.proposal-row time{display:none}.proposal-actions{grid-column:2}.result-item{align-items:flex-start;flex-wrap:wrap}.result-item .select-btn{width:100%}}
</style>
